#!/usr/bin/env node

require('dotenv').config();
const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const CANONICAL_MIGRATION_ID = '20260214000000_canonical_postgresql';
const MIGRATION_LOCK_CONTENT = [
  '# Please do not edit this file manually',
  '# It should be added in your version-control system (i.e. Git)',
  'provider = "postgresql"',
  '',
].join('\n');

function validatePostgresUrl(databaseUrl) {
  if (!databaseUrl || !databaseUrl.trim()) {
    throw new Error(
      'DATABASE_URL is not set. Set it to a PostgreSQL URL, e.g. postgresql://user:pass@host:5432/dbname.'
    );
  }

  const trimmedUrl = databaseUrl.trim();
  if (/^file:/i.test(trimmedUrl)) {
    throw new Error(
      'DATABASE_URL points to SQLite. Use a PostgreSQL URL for production migration generation.'
    );
  }

  if (!/^postgres(ql)?:\/\//i.test(trimmedUrl)) {
    throw new Error(
      `DATABASE_URL "${databaseUrl}" is invalid. Expected postgresql://... or postgres://...`
    );
  }

  return trimmedUrl;
}

function ensureMigrationLock(migrationsDir) {
  fs.mkdirSync(migrationsDir, { recursive: true });
  const lockPath = path.join(migrationsDir, 'migration_lock.toml');
  fs.writeFileSync(lockPath, MIGRATION_LOCK_CONTENT, 'utf8');
}

function clearMigrationDirectories(migrationsDir) {
  if (!fs.existsSync(migrationsDir)) {
    return;
  }

  for (const entry of fs.readdirSync(migrationsDir, { withFileTypes: true })) {
    if (entry.isDirectory()) {
      fs.rmSync(path.join(migrationsDir, entry.name), { recursive: true, force: true });
    }
  }
}

function buildMigrationSql(projectRoot) {
  return execSync('npx prisma migrate diff --from-empty --to-schema-datamodel prisma/schema.prisma --script', {
    cwd: projectRoot,
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'inherit'],
  });
}

function createCanonicalMigration({ projectRoot, migrationId = CANONICAL_MIGRATION_ID }) {
  const migrationsDir = path.join(projectRoot, 'prisma', 'migrations');
  clearMigrationDirectories(migrationsDir);
  ensureMigrationLock(migrationsDir);

  const sql = buildMigrationSql(projectRoot);
  const migrationDir = path.join(migrationsDir, migrationId);
  fs.mkdirSync(migrationDir, { recursive: true });
  fs.writeFileSync(path.join(migrationDir, 'migration.sql'), sql, 'utf8');

  return {
    migrationId,
    migrationDir,
    migrationSqlPath: path.join(migrationDir, 'migration.sql'),
  };
}

function parseMigrationId(argv) {
  const flag = argv.find((arg) => arg.startsWith('--migration-id='));
  if (!flag) {
    return CANONICAL_MIGRATION_ID;
  }

  const value = flag.split('=')[1]?.trim();
  if (!value) {
    throw new Error('Invalid --migration-id value. Example: --migration-id=20260214000000_canonical_postgresql');
  }

  if (!/^[0-9]{14}_[a-z0-9_]+$/i.test(value)) {
    throw new Error('Invalid --migration-id format. Use: yyyymmddhhmmss_name');
  }

  return value;
}

function run({
  databaseUrl = process.env.DATABASE_URL,
  argv = process.argv.slice(2),
  projectRoot = path.resolve(__dirname, '..'),
} = {}) {
  const validatedUrl = validatePostgresUrl(databaseUrl);
  const migrationId = parseMigrationId(argv);

  console.log('🚀 Production Migration Generator');
  console.log('=================================');
  console.log('');
  console.log(`✅ DATABASE_URL looks good: ${validatedUrl.split('@')[0]}@[HIDDEN]`);
  console.log('');
  console.log('1) Generating PostgreSQL schema...');
  execSync('node prisma/generate-schema.js --schema-only', { cwd: projectRoot, stdio: 'inherit' });

  console.log('2) Rebuilding canonical migration set...');
  const result = createCanonicalMigration({ projectRoot, migrationId });

  console.log('');
  console.log('✅ Success! Canonical PostgreSQL migration written:');
  console.log(`   prisma/migrations/${result.migrationId}/migration.sql`);
  console.log('');

  return result;
}

if (require.main === module) {
  try {
    run();
  } catch (error) {
    console.error(`❌ ${error.message}`);
    process.exit(1);
  }
}

module.exports = {
  CANONICAL_MIGRATION_ID,
  MIGRATION_LOCK_CONTENT,
  validatePostgresUrl,
  parseMigrationId,
  createCanonicalMigration,
  run,
};
